/**
 * G193: the Fuelmaker, Blockmaker, Metal Machine and Woodworker play their own SWF states (js/machine-art.js)
 * in the machine rooms and from the pack, instead of a wobbling icon and a drawn ready light; and a job that
 * leaves a tank at 10 or less says "I am low on fuel!" (machine_base lowFuelAlert).
 *
 * The sheets and the table (public/js/machine-art-sheets.js) are generated by tools/build-machine-art.py
 * from the OGA dump; these tests check them against the shipped files, against each SWF's animatee
 * FrameLabels when tinyspeck/glitch-items is present, and run the builder's --check.
 * Run: node --test tests/machine-art.test.js
 */
import { before, describe, it } from 'node:test';
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { existsSync, readFileSync } from 'node:fs';
import { homedir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { inflateSync } from 'node:zlib';
import { MACHINE_ART_LOOPERS, MACHINE_ART_SHEETS } from '../public/js/machine-art-sheets.js';
import {
  LOW_FUEL_BUBBLE_MS,
  LOW_FUEL_LINE,
  LOW_FUEL_REPEAT_MS,
  MACHINE_ART_FPS,
  MACHINE_STATE_MS,
  craftSessionElapsedMs,
  freezeMachineState,
  isLowFuel,
  isMachineArt,
  machineArtHtml,
  machineFrame,
  machineFrameBackground,
  machineFrameRect,
  machineHiresParts,
  machineSheetDef,
  packHandOverState,
  packMakeState,
  roomMachineState,
  setMachineArtFrame,
} from '../public/js/machine-art.js?v=g405-1';
import { MACHINE_IDS } from '../public/js/machines.js?v=g403-1';
import { MACHINE_EXTRA_WAIT_MS, machineTank, tankFuel } from '../public/js/machine-rooms.js?v=g403-1';
import { craftRecipe, ensureMakingItems, loadRecipeCatalogFromFile } from '../public/js/making.js?v=g403-1';
import { platformsScreen } from '../public/js/street-model.js';
import { machineRoomsFeature } from '../public/js/features/machine-rooms-feature.js?v=g405-1';
import { machineArtFeature } from '../public/js/features/machine-art-feature.js?v=g405-1';

const spike = join(dirname(fileURLToPath(import.meta.url)), '..');
const pub = join(spike, 'public');
const audit = [process.env.GLITCH_AUDIT, dirname(spike), join(homedir(), 'Documents/glitch-audit')]
  .find((d) => d && existsSync(join(d, 'glitch-items')));
const gsjs = join(spike, '../glitch-GameServerJS');
const read = (file) => readFileSync(join(pub, file), 'utf8');
const STATES = ['assembled', 'loadOpen', 'loadOpenHold', 'loadClose', 'active', 'ready', 'collectOpen', 'collectOpenHold', 'collectClose'];

/** Width and height of a lossless (VP8L) or extended (VP8X) WebP. */
function webpSize(file) {
  const b = readFileSync(file);
  assert.equal(b.toString('ascii', 8, 12), 'WEBP', file);
  const kind = b.toString('ascii', 12, 16);
  if (kind === 'VP8L') {
    const bits = b.readUInt32LE(21);
    return [(bits & 0x3fff) + 1, ((bits >> 14) & 0x3fff) + 1];
  }
  return [b.readUIntLE(24, 3) + 1, b.readUIntLE(27, 3) + 1];
}

/** [{label: frames}] per DefineSprite with FrameLabels, from a CWS/FWS SWF. Data only. */
function spriteLabels(file) {
  const raw = readFileSync(file);
  const body = raw.toString('ascii', 0, 3) === 'CWS' ? inflateSync(raw.subarray(8)) : raw.subarray(8);
  function* tags(buf, i, end) {
    while (i < end) {
      const head = buf.readUInt16LE(i); i += 2;
      let len = head & 0x3f;
      if (len === 0x3f) { len = buf.readUInt32LE(i); i += 4; }
      yield [head >> 6, buf.subarray(i, i + len)];
      i += len;
      if (head >> 6 === 0) return;
    }
  }
  const out = [];
  for (const [code, data] of tags(body, Math.ceil((5 + 4 * (body[0] >> 3)) / 8) + 4, body.length)) {
    if (code !== 39) continue;
    let frame = 0;
    const labels = [];
    for (const [c, t] of tags(data, 4, data.length)) {
      if (c === 1) frame += 1;
      else if (c === 43) labels.push([t.toString('latin1', 0, t.indexOf(0)), frame]);
    }
    if (labels.length) out.push(Object.fromEntries(labels.map(([n, at], k) => [n, (labels[k + 1]?.[1] ?? frame) - at])));
  }
  return out;
}

describe('G193 machine art: the sheets', () => {
  it('cover the four machines, every state in order, contiguous', () => {
    assert.deepEqual(Object.keys(MACHINE_ART_SHEETS).sort(), [...MACHINE_IDS].sort());
    for (const [id, s] of Object.entries(MACHINE_ART_SHEETS)) {
      assert.deepEqual(Object.keys(s.states), STATES, id);
      let at = 0;
      for (const st of STATES) {
        assert.equal(s.states[st][0], at, `${id} ${st} first`);
        at += s.states[st][1];
      }
      assert.equal(at, s.frames, `${id} frames`);
      assert.equal(s.fps, 30, `${id}: TSEngineConstants.TARGET_FRAMERATE`);
      assert.ok(s.ax > 0 && s.ax < s.fw && s.ay > 0 && s.ay <= s.fh, `${id} anchor`);
      assert.ok(s.fw * s.scale <= 112 && s.fh * s.scale <= 104 && s.scale <= 1.6, `${id} scale`);
      assert.deepEqual(webpSize(join(pub, s.url)), [s.cols * s.fw, Math.ceil(s.frames / s.cols) * s.fh], s.url);
      assert.ok(s.cols * s.fw <= 2048, `${id} sheet width`);
    }
    // Loopers are the .fla's (e.g. fuelmaker.fla: loopers = [... 'loadOpenHold', 'active', 'ready', 'collectOpenHold']).
    assert.deepEqual([...MACHINE_ART_LOOPERS], ['assembled', 'loadOpenHold', 'active', 'ready', 'collectOpenHold']);
    assert.equal(MACHINE_ART_FPS, 30);
  });

  it('frame counts are each SWF animatee\'s labels (not the root layer\'s)', { skip: !audit && 'glitch-items missing' }, () => {
    for (const [id, s] of Object.entries(MACHINE_ART_SHEETS)) {
      const rows = spriteLabels(join(audit, 'glitch-items/tools', id, `${id}.swf`)).filter((r) => r.active && r.ready);
      const labels = rows.sort((a, b) => Object.keys(b).length - Object.keys(a).length)[0];
      for (const st of STATES) assert.equal(s.states[st][1], labels[st], `${id} ${st}`);
    }
    // The two that differ from the root timeline's `states` layer.
    assert.equal(MACHINE_ART_SHEETS.metalmaker.states.collectOpen[1], 14);
    assert.equal(MACHINE_ART_SHEETS.blockmaker.states.loadClose[1], 19);
  });

  it('the sheets and the table are current (tools/build-machine-art.py --check)', { skip: !existsSync('/opt/homebrew/bin/python3.11') && 'python3.11 missing' }, () => {
    const out = execFileSync('python3.11', ['-I', join(spike, 'tools/build-machine-art.py'), '--check'], { encoding: 'utf8' });
    assert.match(out, /^ok/m);
  });
});

describe('G193 machine art: which state shows when', () => {
  before(() => freezeMachineState(''));

  it('uses the GSJS timers', { skip: !existsSync(gsjs) && 'GSJS missing' }, () => {
    const making = readFileSync(join(gsjs, 'players/inc_making.js'), 'utf8');
    const fm = readFileSync(join(gsjs, 'items/fuelmaker.js'), 'utf8');
    assert.match(making, /item\.setAndBroadcastState\('loadOpen'\);\s*item\.apiSetTimer\('onLidClose', 1100\);/);
    assert.match(fm, /function onLidClose\(\)\{[^}]*setAndBroadcastState\('loadClose'\);\s*this\.apiSetTimer\('onActive', 1100\);/);
    assert.match(fm, /this\.setAndBroadcastState\('collectOpen'\);[\s\S]{0,700}?this\.apiSetTimerX\('onCollect', 3000, pc\);/);
    assert.match(fm, /function onCollect\(pc\)\{[^}]*'collectClose'\);\s*this\.apiSetTimerX\('blinkReadyLight', 1000, pc, "collected"\);/);
    assert.match(fm, /function lowFuelAlert\(\)\{[^}]*?if \(this\.getInstanceProp\('fuel_level'\) <= 10\)\{\s*this\.sendBubble\('I am low on fuel!', 10000\);\s*this\.apiSetTimer\('lowFuelAlert', 30\*1000\);/);
    assert.deepEqual({ ...MACHINE_STATE_MS }, { lidOpen: 1100, lidClose: 1100, collectOpen: 3000, collectClose: 1000, handReady: 1000, handOpen: 1000 });
    assert.equal(MACHINE_STATE_MS.lidOpen + MACHINE_STATE_MS.lidClose, MACHINE_EXTRA_WAIT_MS);
    assert.deepEqual([LOW_FUEL_LINE, LOW_FUEL_BUBBLE_MS, LOW_FUEL_REPEAT_MS], ['I am low on fuel!', 10000, 30000]);
  });

  it('a room machine: idle, a job (open, close, active), ready while it waits, collect, idle', () => {
    const t0 = 1_000_000;
    const job = { startedAt: t0, readyAt: t0 + 12_200 };
    assert.deepEqual(roomMachineState({}, t0), { state: 'assembled', since: 0 });
    assert.deepEqual(roomMachineState({ job }, t0 + 10), { state: 'loadOpen', since: t0 });
    assert.deepEqual(roomMachineState({ job }, t0 + 1100), { state: 'loadClose', since: t0 + 1100 });
    assert.deepEqual(roomMachineState({ job }, t0 + 2200), { state: 'active', since: t0 + 2200 });
    assert.equal(roomMachineState({ job }, t0 + 12_199).state, 'active');
    // Done: the job leaves and the output waits (setContents -> blinkReadyLight 'done').
    assert.equal(roomMachineState({ waiting: true }, t0 + 12_200).state, 'ready');
    assert.equal(roomMachineState({ waiting: true }, t0 + 99_000_000).state, 'ready');
    const c = t0 + 20_000;
    assert.deepEqual(roomMachineState({ collectedAt: c }, c + 5), { state: 'collectOpen', since: c });
    assert.deepEqual(roomMachineState({ collectedAt: c }, c + 3000), { state: 'collectClose', since: c + 3000 });
    assert.deepEqual(roomMachineState({ collectedAt: c }, c + 4000), { state: 'assembled', since: 0 });
    // A job started after a Collect wins.
    assert.equal(roomMachineState({ job: { startedAt: c + 100, readyAt: c + 9000 }, collectedAt: c }, c + 200).state, 'loadOpen');
  });

  it('a pack machine: the same start in the Make panel, then the hand-over in the result', () => {
    assert.equal(packMakeState(0).state, 'loadOpen');
    assert.equal(packMakeState(1099).state, 'loadOpen');
    assert.equal(packMakeState(1100).state, 'loadClose');
    assert.deepEqual(packMakeState(5000), { state: 'active', since: 2200 });
    const seq = [0, 999, 1000, 1999, 2000, 2999, 3000].map((ms) => packHandOverState(ms).state);
    assert.deepEqual(seq, ['ready', 'ready', 'collectOpen', 'collectOpen', 'collectClose', 'collectClose', 'assembled']);
    // The first unit carries the 2200 ms (making.js craftUnitDurations), so elapsed runs across units.
    assert.equal(craftSessionElapsedMs({ completed: 0, unitElapsedMs: 700, durations: [4700, 2500] }), 700);
    assert.equal(craftSessionElapsedMs({ completed: 1, unitElapsedMs: 300, durations: [4700, 2500] }), 5000);
    assert.equal(craftSessionElapsedMs({ completed: 2, unitElapsedMs: 0, durationMs: 1000 }), 2000);
  });

  it('frames: loopers loop at 30 fps, the rest play once and stop on their Hold or last frame', () => {
    const s = MACHINE_ART_SHEETS.fuelmaker.states;
    assert.equal(machineFrame('fuelmaker', 'assembled', 99999), s.assembled[0]);
    assert.equal(machineFrame('fuelmaker', 'active', 0), s.active[0]);
    assert.equal(machineFrame('fuelmaker', 'active', 1000), s.active[0] + 30);
    assert.equal(machineFrame('fuelmaker', 'active', (40 * 1000) / 30), s.active[0], 'active loops after 40 frames');
    assert.equal(machineFrame('fuelmaker', 'ready', 500), s.ready[0] + (15 % 14));
    assert.equal(machineFrame('fuelmaker', 'loadOpen', 100), s.loadOpen[0] + 3);
    assert.equal(machineFrame('fuelmaker', 'loadOpen', 1050), s.loadOpenHold[0], 'loadOpen goes on to its Hold');
    assert.equal(machineFrame('fuelmaker', 'collectOpen', 2000), s.collectOpenHold[0]);
    assert.equal(machineFrame('fuelmaker', 'loadClose', 1000), s.loadClose[0] + s.loadClose[1] - 1, 'loadClose stops');
    assert.equal(machineFrame('fuelmaker', 'collectClose', 5000), s.collectClose[0] + s.collectClose[1] - 1);
    assert.equal(machineFrame('fuelmaker', 'nope', 0), -1);
    assert.equal(machineFrame('pick', 'active', 0), -1);
    const rect = machineFrameRect('metalmaker', 17);
    assert.deepEqual(rect, { x: 2 * 129, y: 216, w: 129, h: 216 });
    assert.deepEqual(machineSheetDef('woodworker'), { path: 'assets/sprites/machines/woodworker-states.webp', fw: 133, fh: 146, cols: 15, frames: 95 });
  });

  it('a QA freeze shows one state everywhere, looping it', () => {
    try {
      assert.equal(freezeMachineState('loadClose'), 'loadClose');
      assert.equal(roomMachineState({}, 5).state, 'loadClose');
      assert.equal(packHandOverState(0).state, 'loadClose');
      const s = MACHINE_ART_SHEETS.woodworker.states.loadClose;
      assert.equal(machineFrame('woodworker', 'loadClose', (12 * 1000) / 30), s[0] + 2, 'frozen once states loop');
      assert.equal(freezeMachineState('bogus'), '');
    } finally {
      freezeMachineState('');
    }
  });

  it('low fuel is 10 or less', () => {
    assert.equal(isLowFuel(10), true);
    assert.equal(isLowFuel(0), true);
    assert.equal(isLowFuel(11), false);
    assert.equal(isLowFuel(undefined), false);
    assert.equal(isMachineArt('blockmaker'), true);
    assert.equal(isMachineArt('still'), false);
  });

  it('the Make panel span shows one cell and moves by background position', () => {
    assert.equal(machineArtHtml('frying_pan'), null);
    const html = machineArtHtml('blockmaker', { label: 'Blockmaker working' });
    assert.match(html, /class="mp-tool mp-tool-machine" data-machine-art="blockmaker"/);
    assert.match(html, /width:143px;height:183px;background-image:url\('assets\/sprites\/machines\/blockmaker-states\.webp'\);background-size:2002px 1464px/);
    assert.match(html, /--mp-scale:0\.51/);
    const el = { dataset: { machineArt: 'blockmaker' }, style: {} };
    setMachineArtFrame(el, 'ready', 0);
    const k = MACHINE_ART_SHEETS.blockmaker.states.ready[0];
    assert.equal(el.style.backgroundPosition, `${-(k % 14) * 143}px ${-Math.floor(k / 14) * 183}px`);
    assert.equal(el.dataset.machineState, 'ready');
  });
});

describe('G193 machine art: wiring', () => {
  it('room machines draw the states and lost the wobble and drawn light', () => {
    const src = read('js/features/machine-rooms-feature.js');
    assert.match(src, /from '\.\.\/machine-art\.js\?v=g405-1'/);
    assert.match(src, /roomMachineState\(\{ job, waiting, collectedAt: collectedAt\[m\.def\.id\] \}, t\)/);
    assert.match(src, /m\.sprite\.texture = m\.frames\[k\]/);
    assert.doesNotMatch(src, /sprite\.rotation|light\.circle|blinkReadyLight: the ready state/);
  });

  it('the Make panel plays a pack machine\'s states and its hand-over', () => {
    const game = read('game.js');
    const css = read('style.css');
    assert.match(game, /import \{[^}]*machineArtHtml[^}]*\} from '\.\/js\/machine-art\.js\?v=g405-1'/);
    assert.match(game, /\|\| machineArtHtml\(recipe\.tool, \{ label: /);
    assert.match(game, /const \{ state, since \} = packMakeState\(ms\);\n\s+setMachineArtFrame\(machineArt, state, ms - since\);/);
    assert.match(game, /playMachineHandOver\(resEl\.querySelector\('\[data-machine-art\]'\)\)/);
    // A pack machine left at 10 fuel or less says so over itself in the result (lowFuelAlert's bubble).
    assert.match(game, /isMachineArt\(record\.recipe\.tool\) && isLowFuel\(result\.toolUse\?\.remaining\)\) \{\n[^\n]*\n\s+record\.lowFuel = true;/);
    assert.match(game, /showMakeResult\(record\.lowFuel \? \{ \.\.\.result, lowFuel: true \} : result, record\.key\)/);
    assert.match(game, /result\.lowFuel \? `<span class="mr-machine-say" role="status">\$\{LOW_FUEL_LINE\}<\/span>`/);
    assert.match(css, /\.make-progress \.mp-tool-machine,\n\.make-result \.mr-machine \{[\s\S]*?animation: none;[\s\S]*?transform: translateX\(-50%\) scale\(var\(--mp-scale\)\);/);
    assert.match(read('js/features/index.js'), /import \{ machineArtFeature \} from '\.\/machine-art-feature\.js\?v=g405-1'; FEATURES\.push\(machineArtFeature\);/);
  });
});

describe('G193 low fuel in a machine room', () => {
  class Obj {
    constructor() {
      this.anchor = { set() {} };
      this.children = [];
    }
    addChild(c) { this.children.push(c); return c; }
  }
  class Gfx extends Obj {
    clear() { return this; }
    roundRect() { return this; }
    fill() { return this; }
  }
  const PIXI = { Sprite: Obj, Container: Obj, Graphics: Gfx, ImageSource: class { on() {} emit() {} }, Texture: class { constructor(o) { Object.assign(this, o); } } };
  const ROOM = 'GCR101Q98A12EHH';
  let clock = 5_000_000;
  const realNow = Date.now;

  before(async () => {
    await loadRecipeCatalogFromFile(join(pub, 'assets/content/recipes.json'));
    ensureMakingItems();
  });

  function roomEngine(shared) {
    const room = JSON.parse(readFileSync(join(pub, 'assets/streets', `${ROOM}.json`), 'utf8'));
    const engine = {
      PIXI,
      street: room,
      streetTsid: ROOM,
      entityLayer: new Obj(),
      platforms: platformsScreen(room),
      player: { x: 600, y: 570 },
      pc: { energy: 100, mood: 50, xp: 0, imagination: 0, level: 5, energyMax: 100, imaginationUpgrades: [] },
      inv: shared.inv,
      learnedSkills: ['fuelmaking_1', 'blockmaking_1', 'woodworking_1', 'metalwork_1'],
      streetSlot: (id, t) => ((shared.slots[`${id}:${t}`] ||= {})),
      register: (t) => ((shared.registered ||= []).push(t), t),
      setData: (k, v) => { shared.data[k] = v; },
      param: () => null,
      pushActivity() {},
      toast() {},
      say: (target, line, ms) => shared.said.push([target.classId, line, ms]),
      floatText() {},
      updateHud() {},
      refreshPack() {},
      save() {},
      playSound() {},
      playSoundLoop: () => ({ stop() {} }),
      achievement() {},
      openMakeStation: (station) => { engine.station = station; },
      makeStationJob: ({ key, qty, hold, tool, toolState }) => {
        const out = { made: 0, xp: 0, msgs: [] };
        for (let i = 0; i < qty; i++) {
          const r = craftRecipe(hold, engine.pc, key, { learned: engine.learnedSkills, requireSkill: true, requireTool: true, toolState, stationTool: tool, unitIndex: i + 1, batchQty: qty });
          if (!r.ok) { out.msgs.push(...r.msgs); break; }
          out.made += 1;
        }
        return out;
      },
    };
    return engine;
  }

  it('a job that leaves the tank at 10 or less says so, again every 30 s, until refuelled', () => {
    const prev = globalThis.PIXI;
    globalThis.PIXI = PIXI;
    Date.now = () => clock;
    try {
      machineRoomsFeature._reset();
      const shared = { inv: { plank: 8, fuel_cell: 1 }, slots: {}, data: {}, said: [] };
      const engine = roomEngine(shared);
      machineRoomsFeature.onStreetClear(engine);
      machineRoomsFeature.onStreetEnter(engine.street, engine);
      const ww = shared.registered.find((t) => t.classId === 'woodworker');
      const id = ww.roomMachine;
      // Board burns 1 fuel (catalog_recipes.js 253): a tank of 11 ends at 10.
      const tank = shared.slots[`machine-rooms:${ROOM}`].tanks[id];
      tank.condition.woodworker.remaining = 11;
      machineRoomsFeature.runVerb(ww, 'use', engine);
      const board = { id: '253', name: 'Board', waitMs: 2500, inputs: [{ classTsid: 'plank', qty: 4 }] };
      assert.equal(engine.station.startJob({ key: 'board', recipe: board, qty: 1, waitMultiplier: 1 }), true);
      clock += 2500 + MACHINE_EXTRA_WAIT_MS + 10;
      machineRoomsFeature.onTick(300, clock, engine);
      assert.equal(tankFuel(tank, 'woodworker'), 10);
      assert.deepEqual(shared.said.filter((r) => r[1] === LOW_FUEL_LINE), [['woodworker', LOW_FUEL_LINE, 10000]]);
      clock += LOW_FUEL_REPEAT_MS - 1000;
      machineRoomsFeature.onTick(300, clock, engine);
      assert.equal(shared.said.filter((r) => r[1] === LOW_FUEL_LINE).length, 1, 'not before 30 s');
      clock += 1500;
      machineRoomsFeature.onTick(300, clock, engine);
      assert.equal(shared.said.filter((r) => r[1] === LOW_FUEL_LINE).length, 2, 'again after 30 s');
      // Refuel past 10 and the alert stops.
      machineRoomsFeature.runVerb(ww, 'refuel', engine);
      assert.ok(tankFuel(tank, 'woodworker') > 10);
      clock += LOW_FUEL_REPEAT_MS + 10;
      machineRoomsFeature.onTick(300, clock, engine);
      assert.equal(shared.said.filter((r) => r[1] === LOW_FUEL_LINE).length, 2);
      assert.deepEqual(machineRoomsFeature._state().lowFuelNext, {});
      // A tank that was already full never says it.
      assert.ok(!isLowFuel(tankFuel(machineTank(null, 'fuelmaker'), 'fuelmaker')));
    } finally {
      machineRoomsFeature._reset();
      Date.now = realNow;
      globalThis.PIXI = prev;
    }
  });

  it('the QA feature freezes the state from &machineartstate', () => {
    const data = {};
    try {
      machineArtFeature.init({ param: (n) => (n === 'machineartstate' ? 'ready' : null), setData: (k, v) => { data[k] = v; } });
      assert.equal(data.machineArtState, 'ready');
      assert.equal(roomMachineState({}, 0).state, 'ready');
    } finally {
      machineArtFeature._reset();
    }
    assert.equal(roomMachineState({}, 0).state, 'assembled');
  });
});

/**
 * Root-timeline PlaceObject2 of each named character in a CWS/FWS SWF: { id, name, sx, sy } (matrix scale,
 * 1 when the matrix has none). Data only.
 */
function rootPlacements(file) {
  const raw = readFileSync(file);
  const body = raw.toString('ascii', 0, 3) === 'CWS' ? inflateSync(raw.subarray(8)) : raw.subarray(8);
  let i = Math.ceil((5 + 4 * (body[0] >> 3)) / 8) + 4;
  const out = [];
  while (i < body.length) {
    const head = body.readUInt16LE(i); i += 2;
    let len = head & 0x3f;
    if (len === 0x3f) { len = body.readUInt32LE(i); i += 4; }
    const code = head >> 6;
    const t = body.subarray(i, i + len);
    i += len;
    if (code === 0) break;
    if (code !== 26) continue;
    const flags = t[0];
    if (!(flags & 0x02) || !(flags & 0x20)) continue;
    let p = 3;
    const id = t.readUInt16LE(p); p += 2;
    let sx = 1, sy = 1;
    if (flags & 0x04) {
      let bit = p * 8;
      const read = (n) => { let v = 0; for (let k = 0; k < n; k++, bit++) v = (v << 1) | ((t[bit >> 3] >> (7 - (bit & 7))) & 1); return v; };
      const signed = (n) => { const v = read(n); return n && v >> (n - 1) ? v - 2 ** n : v; };
      if (read(1)) { const n = read(5); sx = signed(n) / 65536; sy = signed(n) / 65536; }
      if (read(1)) { const n = read(5); signed(n); signed(n); }
      const n = read(5); signed(n); signed(n);
      p = Math.ceil(bit / 8);
    }
    if (flags & 0x08) continue; // a colour transform would come next (none on these placements)
    if (flags & 0x10) p += 2;
    const name = t.toString('latin1', p, t.indexOf(0, p));
    out.push({ id, name, sx: +sx.toFixed(3), sy: +sy.toFixed(3) });
  }
  return out;
}

describe('G201 / G292 machine art: 3x parts from each animatee clip', () => {
  const manifest = JSON.parse(readFileSync(join(spike, 'tools/vector-sprites/machines.json'), 'utf8'));
  const results = JSON.parse(readFileSync(join(spike, 'tools/vector-sprites/results.json'), 'utf8'));

  it('the Fuelmaker\'s root places its animatee at 0.9, so it renders at zoom 2.7; the other three are unscaled', { skip: !audit && 'glitch-items missing' }, () => {
    const want = { blockmaker: [69, 'blockmaker', 1], fuelmaker: [57, 'fuelmaker', 0.9], metalmaker: [108, 'metalmaker', 1], woodworker: [45, 'woodworker_mc', 1] };
    for (const [id, [sprite, name, scale]] of Object.entries(want)) {
      const placed = rootPlacements(join(audit, 'glitch-items/tools', id, `${id}.swf`)).find((r) => r.id === sprite);
      assert.ok(placed, `${id}: root places sprite ${sprite}`);
      assert.equal(placed.name, name, id);
      assert.equal(placed.sx, scale, `${id} scale x`);
      assert.equal(placed.sy, scale, `${id} scale y`);
      const job = manifest.jobs.find((j) => j.name === `machine-${id}`);
      assert.equal(job.sprite, sprite, id);
      assert.equal(job.zoom ?? 3, +(3 * scale).toFixed(3), `${id} zoom`);
    }
  });

  it('all four sheets passed against the OGA recordings and ship their parts at 3x the cells', () => {
    for (const [id, s] of Object.entries(MACHINE_ART_SHEETS)) {
      const r = results[s.url];
      assert.equal(r?.status, 'ok', `${id}: ${r?.reason || ''}`);
      assert.ok(r.score >= 0.98 && r.minFrame >= 0.97, `${id} score ${r.score} min ${r.minFrame}`);
      assert.equal(r.cells, s.frames, id);
      let next = 0;
      for (const part of r.parts) {
        assert.equal(part.from, next, `${id} parts run in frame order`);
        next += part.count;
        assert.deepEqual(webpSize(join(pub, part.hires)), [part.cols * s.fw * 3, Math.ceil(part.count / part.cols) * s.fh * 3], part.hires);
      }
      assert.equal(next, s.frames, `${id} parts cover every frame`);
    }
    assert.equal(results[MACHINE_ART_SHEETS.fuelmaker.url].zoom, 2.7);
  });

  it('the Make panel uses the parts when it would stretch the 1x art, and moves across them', () => {
    assert.equal(machineHiresParts('fuelmaker', 1), null, 'DPR 1: 0.64 device pixels per art pixel');
    assert.equal(machineHiresParts('metalmaker', 2), null, 'DPR 2: 0.86');
    assert.ok(machineHiresParts('blockmaker', 2), 'DPR 2: 1.02');
    for (const id of Object.keys(MACHINE_ART_SHEETS)) assert.ok(machineHiresParts(id, 3), `${id} at DPR 3`);
    assert.equal(machineHiresParts('frying_pan', 3), null);
    assert.doesNotMatch(machineArtHtml('fuelmaker', { dpr: 1 }), /data-machine-hires/);
    const html = machineArtHtml('blockmaker', { dpr: 3 });
    assert.match(html, /data-machine-hires="3"/);
    assert.match(html, /background-image:url\('assets\/sprites\/machines\/blockmaker-states\.p1@3x\.webp'\);background-size:1287px 1098px;background-position:0px 0px/);
    const el = { dataset: { machineArt: 'blockmaker', machineHires: '3', machinePart: "url('assets/sprites/machines/blockmaker-states.p1@3x.webp')" }, style: {} };
    const ready = MACHINE_ART_SHEETS.blockmaker.states.ready[0]; // frame 79: the second part (53-105)
    setMachineArtFrame(el, 'ready', 0);
    const j = ready - 53;
    assert.equal(el.style.backgroundImage, "url('assets/sprites/machines/blockmaker-states.p2@3x.webp')");
    assert.equal(el.style.backgroundSize, '1287px 1098px');
    assert.equal(el.style.backgroundPosition, `${-(j % 9) * 143}px ${-Math.floor(j / 9) * 183}px`);
    assert.deepEqual(machineFrameBackground('blockmaker', ready), {
      image: "url('assets/sprites/machines/blockmaker-states.webp')",
      size: '2002px 1464px',
      position: `${-(ready % 14) * 143}px ${-Math.floor(ready / 14) * 183}px`,
    });
  });
});
